-- Rifts World Book 12: Psyscape - its gear. 19 new rows: Psi-Cola (printed
-- 84-89), the seven Psi-Implants of Note (printed 152-153), and the Psionic
-- Devices and Techno-Wizard Machines (printed 154-156).
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-psyscape-gear.sql
--
-- ALL 19 ARE NEW - catalog-diff --table gear --remote, 2026-09-25, run
-- immediately before this file was written. No nearest match was the same item.
--
-- EVERY NUMBER on printed 152-156 WAS READ OFF A RENDER as well as the text
-- layer. They agree except in two places, both on printed 153, and the render
-- wins both: the Eruptor Implant's last band is 91-00 (the text layer prints
-- 97-00, leaving a hole the ink does not have), and its first band names the
-- Zapper (the text layer reads "Tapper").
--
-- CONVENTIONS:
--   * The implants are 'cybernetics', like Triax's implants; each is a
--     brain implant priced per unit. Their Psi-Implant Side Effects Table and
--     removal table (printed 149-151) are prose, cited in each description.
--   * Techno-Wizard items take the catalog's `TW ` prefix and the category of
--     what they do, as Madhaven's did: the pistol, rifle and flamethrower are
--     'weapon', the TW helmet 'armor', the tracker, camera and projector
--     'gear'. Their P.P.E. cost to make, spells and components go in the
--     description; cost is the book's credit price.
--   * Where the book prices a range or a floor ("50,000+"), cost is the low
--     end and cost_note says so.
--   * Psi-Cola is 'gear' with a drug- slug, following Triax's and South
--     America's drugs. Fake Psi-Cola (printed 90) is not a row: it is a
--     powerless counterfeit of the same bottle, and it is noted on Psi-Cola.
--   * A mega-damage range for a helmet's M.D.C. stores the low end in mdc.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('drug-psi-cola', 'Psi-Cola', 'rifts', 'gear', NULL, 15, '15-20 credits a 16 oz bottle in the Magic Zone and CS Burbs; 20-40 at Northern Gun, Manistique and the Pecos Empire; 40-70 most other places; up to 150. In CS cities body-chop-shops charge 2-4 times the average.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A magical cola from the Magic Zone, aged on ley lines, sold by the Black Market. A whole 16 oz bottle is needed for any effect. Non-psychics find it foul: a mild stimulant (fatigue slightly slower, 10% more exertion, +2% skills), and six or more bottles a day may grant one minor Sensitive or Physical power (I.S.P. = M.E. + 2D4), kept after detox only 01-05% of the time. Psychics gain 2D6 I.S.P. for 4D6 minutes (master psychics hold it 4D6+12 minutes); more bottles within the hour add 1D4 each, one bottle an hour keeps the 2D6 coming. Minor and major psychics also get 20% more exertion, +5% skills and +1 initiative; addicts gain 1D4 minor powers (any category but Super) and +10% I.S.P. base. Master psychics love the taste and get 30% more exertion, +5% skills and +1 initiative; addicts gain three minor powers, +10% I.S.P., and a chance of one Super power (Mind Melter 01-70%, Mind Bleeder 01-60%, Burster 01-50%, other masters 01-30%). Psi-Stalkers get 10+2D6 P.P.E. from two bottles but grow lazy; Psi-Hounds/Dog Boys sense supernatural evil at +25% range but grow paranoid and nervous; Nega-Psychics and Nullifiers become immune to psionic attack but are -2 initiative, -10% skills and half bonuses without it. Juicers need 20 bottles a day for any bonus or addiction and never gain psi-powers, Crazies 12; supernatural beings and creatures of magic are unaffected. ADDICTION: each bottle within 48 hours of the first means a save vs lethal poison (14+) at -1, cumulative per bottle; a failure followed by more than half a bottle within 48 hours means addiction (six or more bottles a day). Anyone drinking more than two bottles a day rolls on the book''s ten-result Side Effects table (printed 87-88); addicts roll twice and keep both until 15 days of detox. A former addict has a cumulative 20% chance per bottle in 48 hours of relapse. Outlawed in the Coalition States (death for dealers). Fakes in Psi-Cola bottles sell for under 15 credits and do nothing, or worse; real Psi-Cola has a distinct magic signature.', 'Rifts World Book 12: Psyscape p.84-90'),
('psi-blocker-implant', 'Psi-Blocker Implant', 'rifts', 'cybernetics', NULL, 250000, '250,000 credits list; rare psi-implants can cost 2-5 times list. The M.O.M.-style protruding version costs 10-20% less.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Brain implant that works like a permanent, constant Mind Block. No I.S.P. added. The wearer cannot be reached by Telepathy, Empathy, Hypnotic Suggestion, Empathic Transmission, Deaden Senses or Remote Viewing, nor sensed by sensitive psionics, and is +1 to save vs all psionic attacks, +2 vs mind control and +3 vs possession. A trickle nose bleed comes with every save vs psionic attack. A psychic wearing it cannot use those six powers, has every other sensitive power halved (range, duration, effect), and is closed to outside psionic communication. Meant for non-psychics. Maximum three psi-implants; roll once on the Psi-Implant Side Effects Table (printed 149-150) per implant.', 'Rifts World Book 12: Psyscape p.152'),
('psionic-inhibitor-implant', 'Psionic Inhibitor Implant', 'rifts', 'cybernetics', NULL, 500000, '500,000 credits list; fair availability on the Black Market.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'CS brain implant used on psychic criminals, dissidents and prisoners of war: electromagnetic white noise that disrupts psionics. Only half the psychic''s I.S.P. is available, psionic powers cannot be used normally, and automatic abilities such as sensing the supernatural are blocked. To force one power through he concentrates for nearly a full melee round (no physical action, one psionic action that round), spends 10 I.S.P. and saves vs psionic attack against the implant: on a failure the 10 is lost, on a success he pays the 10 plus the power''s cost. Skills are at half and combat bonuses -2; using a Super power brings a nose bleed. Not meant for non-psychics. Roll on the Psi-Implant Side Effects Table (printed 149-150).', 'Rifts World Book 12: Psyscape p.152'),
('psionic-booster-implant', 'Psionic Booster Implant', 'rifts', 'cybernetics', NULL, 300000, '300,000 credits list; crude cheap versions exist.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Brain implant that helps a psychic concentrate. Adds 4D6 to the I.S.P. base; I.S.P. per level and the psychic''s saving throw class do not change. Grants 1D4 more powers from the Sensitive or Physical categories, and ALL his powers get +20% range and duration and +1D6 damage. Requires at least minor psionics. Crude, cheap versions give only +10% range and duration. Roll once on the Psi-Implant Side Effects Table (printed 149-150).', 'Rifts World Book 12: Psyscape p.152'),
('psionic-actuator-implant', 'Psionic Actuator Implant', 'rifts', 'cybernetics', NULL, 400000, '400,000 credits list; crude cheap versions exist.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Brain implant that widens a psychic''s range and raw power, with results that vary from person to person. Adds M.E. x (1D4+1) to the I.S.P. base; I.S.P. per level and saving throw class do not change. Grants 2D4 more powers from the Healing, Sensitive or Physical categories, or eight from any one of them. Requires at least minor psionics. Crude, cheap versions add only M.E. x2 I.S.P. and 1D6+1 powers (or seven from one category). Roll once on the Psi-Implant Side Effects Table (printed 149-150).', 'Rifts World Book 12: Psyscape p.152-153'),
('sensitive-implant', 'Sensitive Implant', 'rifts', 'cybernetics', NULL, 600000, '600,000 credits list; crude cheap versions exist.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Brain implant that stimulates the psionic sensitive part of the brain. Adds 3D6 to the I.S.P. base; I.S.P. per level and saving throw class do not change. Grants 2D4+4 more Sensitive powers, or 1D4 Sensitive powers plus the Psi-Druid''s powers #1-5. Given to a non-psychic it makes him a Minor Psychic with a base of M.E. x2 plus the 3D6, gaining I.S.P. per level from then on, and he rolls twice on the side effects table. Crude, cheap versions add only 2D6 I.S.P. and 2D4+1 Sensitive powers. Roll once on the Psi-Implant Side Effects Table (printed 149-150).', 'Rifts World Book 12: Psyscape p.153'),
('physical-reactor-implant', 'Physical Reactor Implant', 'rifts', 'cybernetics', NULL, 800000, '800,000 credits list; crude cheap versions exist.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Brain implant that stimulates the part of the brain behind physical psionic manifestations. Adds 3D6 to the I.S.P. base; I.S.P. per level and saving throw class do not change. Powers are random (percentile): 01-40 2D4+2 Physical powers; 41-80 1D6+3 Healing powers; 81-90 the Nega-Psychic''s powers #1 and #2 at half range plus 1D4+1 Physical powers; 91-00 two Super powers of choice, excluding Telemechanics and any kinetic/kinesis power. Given to a non-psychic it makes him a Minor Psychic (base M.E. x2 plus the 3D6) and he rolls twice on the side effects table. Crude, cheap versions add only 2D6 I.S.P. and one ability fewer. Roll once on the Psi-Implant Side Effects Table (printed 149-150).', 'Rifts World Book 12: Psyscape p.153'),
('eruptor-implant', 'Eruptor Implant', 'rifts', 'cybernetics', NULL, 1000000, 'One million credits list; crude cheap versions exist.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'CS brain implant first meant to create Zappers and Bursters. Adds 3D6+12 to the I.S.P. base; I.S.P. per level and saving throw class do not change. Powers are random (percentile): 01-20 the Zapper''s R.C.C. abilities #1-4 at half range and duration, plus Electrokinesis and 1D4 Physical powers; 21-40 the Burster''s abilities #1-5 at half range and duration, plus Pyrokinesis and 1D4 Physical powers; 41-60 Master of Telekinesis: Telekinesis (super) at double duration, range and weight, Telekinetic Force Field, and every telekinetic Physical power; 61-80 Energy Shaper: the Psi-Slayer''s Psi-Dagger plus Psi-Sword, Psi-Shield, Mind Bolt and Electrokinesis; 81-90 Bio-Master: Bio-Regeneration, Bio-Manipulation, Psychic Body Field, Psionic Invisibility and three Healing powers; 91-00 Hydrokinesis plus the Mind Bleeder powers Bleed P.E. Energy, Healing Leech and Impervious to Bio-Manipulation, and two Physical powers. I.Q. -1, and the recipient becomes overconfident, aggressive and short-tempered. Given to a non-psychic it makes him a MAJOR Psychic (base M.E. x2 plus the above) but I.Q. drops 20% and he rolls twice on the side effects table. Crude, cheap versions cost another 15% of I.Q. and make the recipient very aggressive and predatory. Roll once on the Psi-Implant Side Effects Table (printed 149-150).', 'Rifts World Book 12: Psyscape p.153'),
('cs-psionic-weapon-gauntlet', 'CS Psionic Weapon Gauntlet', 'rifts', 'weapon', NULL, 1600000, '1.6 million credits; experimental, not sold - no Black Market copies known.', 'Psi-Sword 2D6 M.D.; Electrokinesis 1D6 M.D. punch or 2D6 M.D. blast (double damage and range for a Mind Melter or Psi-Slayer)', 1, 'Electrokinesis blast 30 feet (9 m)', NULL, NULL, NULL, NULL, NULL, 'Experimental CS glove and armature linked to the nervous system and a brain implant, powered mostly by an electromagnetic battery and mini-nuclear cell. Lets even a minor psychic mimic three Super powers, weakly. Psi-Sword: a 3 ft (0.9 m) blade of 2D6 M.D., up to 10 minutes. Psi-Shield: 34+2D6 M.D.C., up to 10 minutes. Each costs 10 I.S.P. and needs a 15-minute break after 5-10 minutes of use. Electrokinesis: 1D6 M.D. electrified punches or 2D6 M.D. blasts at only 30 ft. No I.S.P. augmentation and no known penalties. Field tested by Special Forces, Psi-Battalion and Psi-Net only.', 'Rifts World Book 12: Psyscape p.154'),
('cs-tk-artificial-limbs', 'CS TK Artificial Limbs', 'rifts', 'gear', NULL, 50000, '50,000 credits for a pair of articulated M.D.C. arms and hands; about 75,000 for the version with retractable Vibro-Swords (2D6 M.D.).', NULL, 0, NULL, NULL, NULL, NULL, NULL, 40, 'Experimental CS pair of puppet-like mechanical arms on a padded harness, moved by the wearer''s telekinesis at the speed of thought. Maximum two limbs; P.S. and P.P. 10; each arm 40 M.D.C., each hand 15. Adds one melee attack/action and +1 to strike and parry. No power source: 10 I.S.P. spent as Telekinesis animates them for 20 minutes, and each use of the arms counts as a melee action and uses up a psionic attack that could have been made instead. Minor and major psychics have trouble with them and get none of the bonuses; Nega-Psychics and Psi-Nullifiers cannot use them; most master psychics handle them like natural limbs. Field tested by Special Forces, Psi-Battalion and Psi-Net; likely to be approved for Psi-Battalion.', 'Rifts World Book 12: Psyscape p.154'),
('cs-psi-damper-helmet', 'CS Psi-Damper Helmet', 'rifts', 'armor', NULL, 65000, '65,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 30, 'Mega-damage helmet (30 to 50 M.D.C.) with a lattice of quartz crystals, electrodes and an electromagnetic disrupter that dampens psionic energy; on/off switch. Field tested and approved. +2 to save vs psionic mind control, +1 vs all other psionic attacks, and psionic attack durations are reduced 20%; not effective against most possession. After an hour of use it causes headache and nausea: -1 initiative, -5% skills. A psychic wearer suffers double penalties and -10% Speed. Deployed by Special Forces, Psi-Battalion, the ISS and army units on special assignment.', 'Rifts World Book 12: Psyscape p.154-155'),
('cs-psi-scanner', 'CS Psi-Scanner', 'rifts', 'gear', NULL, 3500, '3,500 credits; good availability through the Black Market, Northern Gun and the Manistique Imperium.', NULL, 0, '4 feet (1.2 m)', NULL, NULL, NULL, NULL, NULL, 'Hand-held wand, used like an old metal detector, that detects a psionic signature in a human or human-looking D-Bee or shapechanger with more than 20 I.S.P. or major/master psionics. Only 01-50% reliable against major and master psychics, +9% if waved over the head within one foot (0.3 m). It shows no power level and cannot tell a supernatural being, creature of magic or nonhuman from a human. Rarely used by the CS itself, popular on secondary markets.', 'Rifts World Book 12: Psyscape p.155'),
('tw-psi-blocker-helmet', 'TW Psi-Blocker Helmet', 'rifts', 'armor', 3, 250000, '250,000+ credits; rare and coveted. Recharge 10 P.P.E. or 20 I.S.P. per 30 minutes of protection.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 35, 'Techno-Wizard version of the CS psi-damper, the best protection against psionic attack and probes. Works as a Mind Block; the wearer is also impervious to See Aura, Sense Evil and Remote Viewing, +2 to save vs psionic mind control and magic illusions, and +1 vs possession. It closes the wearer to helpful probes and communication too, and a psychic wearing it cannot use psi-sensitive powers. 35-45 M.D.C.; weighs 3-5 lbs (1.4-2.3 kg). TW build: 100 P.P.E. to make; spells Mute (50), See Aura (6), Befuddle (3), Energy Disruption (12) and Frequency Jamming (15); tourmaline crystals and an M.D.C. helmet with electrodes and quartz. Deployed by Special Forces, Psi-Battalion and the ISS.', 'Rifts World Book 12: Psyscape p.155'),
('tw-psi-bloodhound-psi-tracker', 'TW Psi-Bloodhound Psi-Tracker', 'rifts', 'gear', NULL, 80000, '80,000 to 100,000 credits; poor availability.', NULL, 0, '400 feet (122 m) at 89% efficiency; -15% per additional 100 feet', NULL, NULL, NULL, NULL, NULL, 'Techno-Wizard scanner like a hand-held computer or mini-radar. Detects psionic energy within 400 ft (122 m) at 01-89%, pinpoints up to five sources (usually the five strongest), and reads their power level: low (minor), medium, high (master psychic) or off the scale. Beyond 400 ft accuracy falls by 15 for every 100 ft or part thereof (74% at 401-500 ft, 59% at 600 ft). It cannot tell mortals from supernatural beings or creatures of magic.', 'Rifts World Book 12: Psyscape p.155'),
('tw-tk-pistol', 'TW TK Pistol', 'rifts', 'weapon', 2, 50000, '50,000+ credits; poor to fair availability. Recharge 10 P.P.E. or 20 I.S.P. (10 I.S.P. gives seven shots rather than 15).', '2D4 M.D. (3D6 M.D. at ley lines)', 1, '600 feet (183 m)', '15 shots', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'Techno-Wizard handgun that looks like an ordinary energy or automatic pistol and fires bullet-hard bolts of telekinetic force. Weighs 2-3 lbs (0.9-1.4 kg). TW build: 35 P.P.E. to make; spells Telekinesis (8) and Energy Bolt (5); the mechanical gun and rose quartz worth 500 credits.', 'Rifts World Book 12: Psyscape p.155'),
('tw-tk-assault-rifle', 'TW TK Assault Rifle', 'rifts', 'weapon', 5, 80000, '80,000+ credits; poor to fair availability. Recharge 20 P.P.E. or 40 I.S.P. (10 I.S.P. gives seven shots, 20 gives 15).', '2D4 M.D. single shot (3D6 at ley lines); 3D6 M.D. three-round burst (5D6 at ley lines)', 1, '1500 feet (457.2 m)', '30 shots', 'Single shots or three-round bursts; a shot or burst counts as one melee attack', NULL, NULL, NULL, 'Larger Techno-Wizard version of the TK pistol, close to a TW TK machinegun, usually built to look like a C-12, NG-457 or L-20 pulse rifle; fires telekinetic bolts singly or in bursts. Weighs 5-8 lbs (2.3-3.6 kg). TW build: 80 P.P.E. to make; spells Telekinesis (8), Energy Bolt (5) and Fly as the Eagle (25); the mechanical rifle and a yellow diamond worth 1500+ credits.', 'Rifts World Book 12: Psyscape p.155-156'),
('tw-flamethrower', 'TW Flamethrower', 'rifts', 'weapon', 8, 80000, '80,000+ credits; poor availability. Recharge 10 P.P.E. or 20 I.S.P. (10 I.S.P. gives seven shots).', '3D6 M.D. single shot (5D6 at ley lines); sustained stream 2D4x10 M.D. on one target for a melee round, or 3D6 M.D. to every six feet (1.8 m) swept', 1, '300 feet (91.5 m)', '15 shots', 'Single shots, or a sustained stream for a whole melee round that counts as five shots', NULL, NULL, NULL, 'Techno-Wizard flamethrower that looks like an ordinary one painted with magic symbols and a fire pattern. Weighs 8-10 lbs (3.6-4.5 kg). TW build: 55 P.P.E. to make; spells Ignite Fire (6), Fireblast (8) and Fire Ball (10); the mechanical weapon with its fuel canister (which holds the magic energy) and a red or orange sapphire worth 1200+ credits.', 'Rifts World Book 12: Psyscape p.156'),
('tw-psychic-camera', 'TW Psychic Camera', 'rifts', 'gear', 0.5, 50000, '50,000+ credits; poor availability. TW macro and telescopic lenses cost 5,000 credits. Recharge 8 P.P.E. or 16 I.S.P. (8 I.S.P. for 50 snapshots).', NULL, 0, 'Standard lens 3-300 feet (0.9-91.5 m)', '100 photographs per roll or disc of film', 'One aimed photo, or three wild snaps, per melee action', NULL, NULL, NULL, 'Techno-Wizard camera with a clear quartz crystal lens that photographs the invisible - entities, spirits, Astral travelers and the magically invisible - and lets the user see them through the lens. A psychic with Telepathy can leave mental images on the film by touch (one melee round each); one with Remote Viewing or Machine Ghost can read the pictures by touch without developing them, 25 per melee round. Weighs 0.5-2 lbs. TW build: 55 P.P.E. to make; spells See the Invisible (4), See Aura (6), Sense Evil (2) and Globe of Daylight (2).', 'Rifts World Book 12: Psyscape p.156'),
('tw-thought-projector', 'TW Thought Projector', 'rifts', 'gear', 15, 90000, '90,000+ credits; poor availability. Recharge 20 P.P.E. or 10 I.S.P. - here I.S.P. is the cheaper fuel.', NULL, 0, 'Projection up to 100 feet (30.5 m) away, double at ley lines', NULL, NULL, NULL, NULL, NULL, 'Techno-Wizard projector, built with psychics in mind, that turns a psychic''s thoughts into three-dimensional moving pictures with sound, smaller than or at life size; a mage gets images only. The image freezes or slows while the psychic talks and runs at real speed when he is silent and concentrating. He wears a wire-frame cap (0.5 lb) and must stay within 60 ft (18.3 m) of the projector (15 lbs). Up to 10 minutes per charge. TW build: 120 P.P.E. to make; spells Globe of Daylight (2), Apparition (20), Illusion Manipulation (60) and Distant Voice (10).', 'Rifts World Book 12: Psyscape p.156');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 19 Psyscape gear rows are in' AS assertion, count(*) AS got, 19 AS want
  FROM gear WHERE source_book LIKE 'Rifts World Book 12: Psyscape p.%';

SELECT 'seven psi-implants as cybernetics' AS assertion, count(*) AS got, 7 AS want
  FROM gear WHERE category = 'cybernetics' AND source_book LIKE 'Rifts World Book 12: Psyscape p.%';

SELECT 'the eruptor reads the ink, 91-00 and Zapper' AS assertion, count(*) AS got, 1 AS want
  FROM gear WHERE slug = 'eruptor-implant' AND cost = 1000000
   AND instr(description, '91-00 Hydrokinesis') > 0 AND instr(description, 'Zapper''s R.C.C.') > 0;

SELECT 'three TW weapons carry mega-damage' AS assertion, count(*) AS got, 3 AS want
  FROM gear WHERE slug IN ('tw-tk-pistol', 'tw-tk-assault-rifle', 'tw-flamethrower')
   AND category = 'weapon' AND is_mega_damage = 1;

INSERT INTO data_script_runs (filename) VALUES ('add-psyscape-gear.sql');
